WITH s AS (
  UPDATE public.sesiones_usuario SET revocado_en = now()
   WHERE token_hash = encode(digest($1::text, 'sha256'), 'hex') AND revocado_en IS NULL
  RETURNING usuario_id
), registro AS (
  INSERT INTO public.auditoria_accesos (usuario_id, correo, evento, ip)
  SELECT usuario_id, $2, 'logout', NULLIF($3, '') FROM s
)
SELECT count(*) AS cerradas FROM s;
